/* ---------- screens ---------- */
.screen { position: absolute; inset: 0; z-index: 40; display: flex; align-items: center; justify-content: center; }
#menu { background: radial-gradient(ellipse at 66% 42%, rgba(30,10,10,.4), rgba(5,4,5,.72) 70%); backdrop-filter: blur(2.5px) saturate(.9); }
.menu-grad {
  position: absolute; inset: 0;
  background: linear-gradient(90deg, rgba(5,4,5,.92) 0%, rgba(5,4,5,.72) 34%, rgba(5,4,5,.16) 65%, rgba(5,4,5,.55) 100%),
             linear-gradient(180deg, rgba(5,4,5,.5), transparent 26%, transparent 72%, rgba(5,4,5,.9));
  pointer-events: none;
}
.menu-content {
  position: relative; width: min(1180px, 92vw); display: flex; flex-direction: column;
  align-items: flex-start; padding-left: 4vw; z-index: 2;
}
.eyebrow { font-family: var(--font-mono); font-size: 9px; letter-spacing: .32em; color: var(--blood-bright); margin-bottom: 14px; }
.logo {
  font-size: clamp(76px, 13vw, 186px); line-height: .78; font-weight: 900; letter-spacing: -.015em;
  color: var(--bone); text-transform: uppercase; position: relative;
  text-shadow: 0 8px 60px rgba(0,0,0,.9), 0 2px 0 rgba(0,0,0,.6);
  background: linear-gradient(180deg, #f2e9dd 0%, #ded2c2 52%, #b9a894 74%, #7d6a5d 100%);
  -webkit-background-clip: text; background-clip: text; -webkit-text-fill-color: transparent;
}
.logo::after {
  content: ''; position: absolute; left: -.5%; right: 6%; bottom: -.14em; height: .09em;
  background: linear-gradient(90deg, var(--rust), var(--blood-bright) 40%, transparent);
  filter: blur(.4px); opacity: .85;
}
.tagline { font-family: var(--font-mono); font-size: clamp(9px, 1.1vw, 12px); letter-spacing: .5em; color: rgba(231,222,209,.6); margin-top: 16px; }
.tagline span { color: var(--blood-bright); }
.blurb { font-size: 17px; line-height: 1.4; color: rgba(231,222,209,.5); margin-top: 18px; letter-spacing: .04em; font-weight: 400; }
.menu-actions { display: flex; gap: 12px; margin-top: 30px; }
.btn {
  pointer-events: auto; cursor: pointer; font-family: var(--font-display); font-weight: 700;
  font-size: 17px; letter-spacing: .26em; padding: 15px 42px 14px; border: 0; position: relative;
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 10px), calc(100% - 10px) 100%, 0 100%);
  transition: transform .12s, filter .15s, background .15s;
}
.btn:active { transform: translateY(1px) scale(.99); }
.btn.primary { background: linear-gradient(160deg, #c21b21, #7e0d12); color: #f5ece0; box-shadow: inset 0 1px 0 rgba(255,255,255,.18), 0 14px 40px rgba(140,10,16,.35); }
.btn.primary:hover { filter: brightness(1.18); }
.btn.ghost { background: rgba(231,222,209,.055); color: rgba(231,222,209,.72); border: 1px solid rgba(231,222,209,.16); padding: 14px 30px; }
.btn.ghost:hover { background: rgba(231,222,209,.11); color: var(--bone); }
.menu-meta { display: flex; gap: 34px; margin-top: 34px; font-family: var(--font-mono); }
.menu-meta div { display: flex; flex-direction: column; gap: 3px; }
.menu-meta span { font-size: 7px; letter-spacing: .24em; color: rgba(231,222,209,.28); }
.menu-meta b { font-size: 13px; letter-spacing: .08em; color: rgba(231,222,209,.6); font-weight: 500; }
.controls-grid {
  display: grid; grid-template-columns: repeat(3, auto); gap: 8px 28px; margin-top: 30px;
  font-family: var(--font-mono); font-size: 8px; letter-spacing: .08em; color: rgba(231,222,209,.34);
}
.controls-grid div { display: flex; align-items: center; gap: 5px; }
.controls-grid span { margin-left: 5px; }
.controls-grid kbd { font-size: 7px; }
.menu-foot { font-family: var(--font-mono); font-size: 7px; letter-spacing: .24em; color: rgba(231,222,209,.18); margin-top: 30px; }

.blood-drip { position: absolute; top: -10px; width: 3px; background: linear-gradient(180deg, #5f070b, #9a1017 40%, #6b080d); opacity: .55; pointer-events: none; border-radius: 0 0 3px 3px; }
.blood-drip::after { content: ''; position: absolute; left: -2px; bottom: -5px; width: 7px; height: 8px; border-radius: 50%; background: #7c0a10; }
.blood-drip.d1 { left: 58%; height: 42vh; animation: drip 9s ease-in-out infinite; }
.blood-drip.d2 { left: 71%; height: 27vh; animation: drip 12s ease-in-out infinite 2s; }
.blood-drip.d3 { left: 84%; height: 18vh; animation: drip 14s ease-in-out infinite 5s; }
@keyframes drip { 0%,100% { transform: scaleY(.94); opacity: .35; } 50% { transform: scaleY(1.03); opacity: .6; } }

.modal {
  position: relative; width: min(560px, 88vw); padding: 40px 44px;
  background: linear-gradient(165deg, rgba(20,15,16,.97), rgba(7,5,6,.98));
  border: 1px solid rgba(231,222,209,.1); border-top: 2px solid var(--blood);
  box-shadow: 0 40px 120px rgba(0,0,0,.9);
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 22px), calc(100% - 22px) 100%, 0 100%);
  text-align: left;
}
.modal h2 { font-size: 68px; font-weight: 900; line-height: .85; letter-spacing: .02em; }
.modal-actions { display: flex; gap: 10px; margin-top: 28px; flex-wrap: wrap; }
.modal-note { font-family: var(--font-mono); font-size: 8px; letter-spacing: .16em; color: rgba(231,222,209,.28); margin-top: 20px; }
.death-modal { border-top-color: var(--blood-bright); }
.death-modal h2 { color: var(--blood-bright); text-shadow: 0 0 60px rgba(229,43,49,.35); }
.death-stats { display: flex; gap: 32px; margin-top: 22px; font-family: var(--font-mono); }
.death-stats div { display: flex; flex-direction: column; gap: 3px; }
.death-stats span { font-size: 8px; letter-spacing: .22em; color: rgba(231,222,209,.3); }
.death-stats b { font-size: 24px; font-weight: 500; color: var(--bone); }
.death-stats div:last-child b { color: var(--blood-bright); }

/* ---------- touch ---------- */
